INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1941---counter-attack-japan', 'Turbografx-16', '1941 - Counter Attack (Japan)', '1990', 'Shooter', 'Capcom', '1', 'Vertical arcade shooter', 'Vertical-scrolling shoot ''em up with WWII themes.', 'Pilot a P-38 Lightning to destroy the invading forces of the Neo Empire.', 'A high-octane SuperGrafx exclusive with impressive sprite rotation.', '1941: Counter Attack for TurboGrafx-16 delivers arcade-perfect shooting action. Experience intense aerial combat and massive bosses in this technically superior 16-bit vertical shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1943-kai-japan', 'Turbografx-16', '1943 Kai (Japan)', '1989', 'Shooter', 'Capcom', '1', 'Vertical arcade shooter', 'Vertical-scrolling shoot ''em up with WWII themes.', 'Navigate the Pacific theater to sink the Japanese battleship Yamato.', 'An enhanced version of 1943 featuring new weapons and faster pacing.', '1943 Kai (Japan) on TurboGrafx-16 is a definitive arcade conversion. Master the "Loop" maneuver and manage your fuel while blasting through waves of enemy fleets in this classic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('21-emon---mezase-hotel-ou!!-japan', 'Turbografx-16', '21 Emon - Mezase Hotel Ou!! (Japan)', '1988', 'Adventure', 'Shin Nihon Computer', '1', 'Anime adventure', 'Board game and business simulation with anime themes.', 'Manage a space hotel and compete in various board-game style challenges.', 'A quirky Japan-exclusive sim based on the 21 Emon anime series.', '21 Emon: Mezase Hotel Ou!! offers a unique blend of strategy and board game mechanics. Navigate the celestial hotel industry in this colorful and charming PC Engine title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventure-island-japan', 'Turbografx-16', 'Adventure Island (Japan)', '1988', 'Platformer', 'Hudson Soft', '1', 'Classic action platformer', 'Side-scrolling platformer with fruit-collecting mechanics.', 'Rescue Princess Leilani by navigating through monster-filled islands.', 'The Japanese version of the classic platforming hit known as Takahashi Meijin.', 'Adventure Island (Japan) for TurboGrafx-16 brings iconic 8-bit action to the 16-bit era. Master the skateboard and fireballs in this vibrant and challenging tropical quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-blasters-japan', 'Turbografx-16', 'Aero Blasters (Japan)', '1989', 'Shooter', 'Kaneko / Hudson Soft', '1', 'Horizontal arcade shooter', 'Horizontal-scrolling shoot ''em up with fast-paced action.', 'Pilot a high-tech fighter to stop an alien biological threat.', 'A stunningly fast and colorful shooter with impressive parallax scrolling.', 'Aero Blasters (Japan) on TurboGrafx-16 is a masterclass in shmup design. Experience high-speed aerial combat and fluid 16-bit graphics in this acclaimed arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-blasters-usa', 'Turbografx-16', 'Aero Blasters (USA)', '1989', 'Shooter', 'Kaneko / Hudson Soft', '1', 'Horizontal arcade shooter', 'Horizontal-scrolling shoot ''em up with fast-paced action.', 'Pilot a high-tech fighter to stop an alien biological threat.', 'The North American release of the high-speed arcade shooting classic.', 'Aero Blasters (USA) delivers intense 16-bit action on the TurboGrafx-16. Battle through futuristic landscapes and massive mechanical bosses in this essential horizontal shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('after-burner-ii-japan', 'Turbografx-16', 'After Burner II (Japan)', '1989', 'Shooter', 'Sega / NEC Avenue', '1', 'Arcade flight shooter', 'Behind-the-back pseudo-3D flight combat.', 'Pilot an F-14 Tomcat through enemy territory to destroy air and ground targets.', 'A faithful port of Sega’s arcade legend featuring intense scaling and speed.', 'After Burner II (Japan) for TurboGrafx-16 captures the raw energy of the arcade. Master the throttle and missiles in this fast-paced 16-bit aerial combat simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-zonk-usa', 'Turbografx-16', 'Air Zonk (USA)', '1992', 'Platformer', 'Red Company', '1', 'Cute action platformer shooter', 'Horizontal-scrolling "cute ''em up" with cyberpunk themes.', 'Pilot Zonk, the futuristic counterpart of Bonk, to save the future.', 'A colorful, high-energy spin-off featuring unique power-ups and rock music.', 'Air Zonk for TurboGrafx-16 is a standout shmup. Experience incredible sprite effects and humorous character designs in this vibrant and fast-paced futuristic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aldynes---the-misson-code-for-rage-crisis-japan', 'Turbografx-16', 'Aldynes - The Misson Code for Rage Crisis (Japan)', '1991', 'Shooter', 'Compile', '1', 'Vertical sci-fi shooter', 'Horizontal-scrolling shoot ''em up with robotic themes.', 'Pilot a transforming craft to defend Earth from an orbital invasion.', 'A SuperGrafx exclusive known for its intense difficulty and 16-bit visuals.', 'Aldynes on TurboGrafx-16 is a technical powerhouse. Utilize a sophisticated drone system and master complex weapon patterns in this elite and rare 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-crush-japan', 'Turbografx-16', 'Alien Crush (Japan)', '1988', 'Pinball', 'Naxat Soft', '1', 'Arcade pinball', 'Sci-fi themed pinball simulation with horror elements.', 'Score points and defeat alien bosses across a biomechanical table.', 'A cult classic pinball game with a dark, atmospheric Giger-esque aesthetic.', 'Alien Crush (Japan) on TurboGrafx-16 features unique bonus stages and amazing audio. Experience the definitive 16-bit pinball game with deep mechanics and sci-fi visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-crush-usa', 'Turbografx-16', 'Alien Crush (USA)', '1988', 'Pinball', 'Naxat Soft', '1', 'Arcade pinball', 'Sci-fi themed pinball simulation with horror elements.', 'Score points and defeat alien bosses across a biomechanical table.', 'The North American version of the legendary biomechanical pinball hit.', 'Alien Crush (USA) brings intense pinball action to the TurboGrafx-16. Master the flippers and uncover secret bonus rooms in this atmospheric and addictive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ankoku-densetsu-japan', 'Turbografx-16', 'Ankoku Densetsu (Japan)', '1988', 'Action', 'Hudson Soft', '1', 'Side-scrolling action', 'Side-scrolling action-platformer with dark fantasy themes.', 'Battle through a world of shadows to defeat the demon king.', 'A gritty action game with impressive atmosphere and large character sprites.', 'Ankoku Densetsu (Japan) for TurboGrafx-16, known as Legendary Axe II in the West, offers a dark and challenging quest. Master multiple weapons in this moody 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aoi-blink-japan', 'Turbografx-16', 'Aoi Blink (Japan)', '1990', 'Platformer', 'West One', '1', 'Colorful action platformer', 'Side-scrolling platformer based on the Osamu Tezuka anime.', 'Journey through magical lands to rescue your father and find the Blue Blink.', 'A charming Japan-exclusive adventure featuring diverse levels and magic.', 'Aoi Blink (Japan) on TurboGrafx-16 is a beautiful tribute to Tezuka''s art style. Navigate imaginative worlds in this polished and family-friendly 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aoi-blink-japan-en-by-gaijin+zatos-v099b', 'Turbografx-16', 'Aoi Blink (Japan) [En by Gaijin+Zatos v0.99b]', '1990', 'Platformer', 'West One', '1', 'Colorful action platformer', 'Side-scrolling platformer with translated dialogue.', 'Journey through magical lands to find your father with the help of Blue Blink.', 'A fan-translated version of the Tezuka anime classic for English players.', 'Aoi Blink [En] for TurboGrafx-16 allows Western fans to fully enjoy the story of the legendary anime creator. Experience this polished platformer with clear English text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('appare-gateball-japan', 'Turbografx-16', 'Appare Gateball (Japan)', '1989', 'Sports', 'Atlus', '1', 'Japanese gateball sports', 'Overhead sports simulation focusing on gateball (croquet).', 'Win matches of gateball by navigating balls through gates with precision.', 'A unique and rare Japan-exclusive sports game featuring colorful graphics.', 'Appare Gateball (Japan) on TurboGrafx-16 brings the traditional Japanese sport to life. Master the angles and power of your shots in this charming 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armed-formation-f-japan', 'Turbografx-16', 'Armed Formation F (Japan)', '1990', 'Shooter', 'Namco', '1', 'Vertical arcade shooter', 'Vertical-scrolling shoot ''em up with a unique formations system.', 'Pilot a craft and adjust your satellite drones to survive alien attacks.', 'A tactical shooter featuring diverse weapon patterns and smooth scrolling.', 'Armed Formation F (Japan) for TurboGrafx-16 offers a strategic take on the shmup genre. Master the drone positioning to overcome waves of robotic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('artist-tool-japan', 'Turbografx-16', 'Artist Tool (Japan)', '1988', 'Utility', 'NEC', '1', 'Drawing and music tool', 'Creative drawing and animation software utility.', 'Use various tools and stamps to create digital art on the PC Engine.', 'A rare Japan-exclusive utility that turns the console into an art studio.', 'Artist Tool (Japan) on TurboGrafx-16 provides a glimpse into early digital creativity. Utilize icons and colors to paint 16-bit masterpieces in this unique software tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-robo-kid-special-japan', 'Turbografx-16', 'Atomic Robo-Kid Special (Japan)', '1989', 'Shooter', 'Uplink', '1', 'Horizontal sci-fi shooter', 'Horizontal-scrolling shoot ''em up with physics-based movement.', 'Navigate complex levels and destroy mechanical bosses as a small robot.', 'A unique shooter where you must manage momentum and multi-directional fire.', 'Atomic Robo-Kid Special (Japan) for TurboGrafx-16 is a refined arcade port. Experience challenging level design and diverse weaponry in this distinct robotic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('av-poker-japan', 'Turbografx-16', 'AV Poker (Japan)', '1989', 'Casino', 'Naxat Soft', '1', 'Poker simulation', 'Digital poker simulation with adult-themed rewards.', 'Win hands of poker to reveal various digitized images.', 'A Japan-exclusive gambling game featuring adult-oriented visual rewards.', 'AV Poker (Japan) on TurboGrafx-16 is a rare curiosity of the Japanese library. Test your luck in this 16-bit rendition of video poker with a mature twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballistix-japan', 'Turbografx-16', 'Ballistix (Japan)', '1991', 'Action', 'Cytox', '1', 'Futuristic sports combat', 'Top-down futuristic sports game with physics-based puck movement.', 'Use bumpers and speed to knock the puck into the opponent''s goal.', 'A fast-paced and chaotic futuristic sports title with scrolling arenas.', 'Ballistix (Japan) for TurboGrafx-16 offers a unique blend of pinball and soccer. Master the ricochets to outsmart your opponents in this high-energy 16-bit game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballistix-usa', 'Turbografx-16', 'Ballistix (USA)', '1991', 'Action', 'Cytox', '1', 'Futuristic sports combat', 'Top-down futuristic sports game with physics-based puck movement.', 'Use bumpers and speed to knock the puck into the opponent''s goal.', 'The North American release of the frantic futuristic sports simulation.', 'Ballistix (USA) brings intense arcade-style competition to the TurboGrafx-16. Control the field with speed and strategy in this visually distinct and rapid-fire title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bari-bari-densetsu-japan', 'Turbografx-16', 'Bari Bari Densetsu (Japan)', '1989', 'Racing', 'Toei Animation', '1', 'Anime motorcycle racing', 'Behind-the-back motorcycle racing based on the manga series.', 'Win high-speed bike races while following the story of Gun Koma.', 'A detailed racing game featuring the characters from the famous manga.', 'Bari Bari Densetsu (Japan) on TurboGrafx-16 offers high-speed bike action. Master the curves and experience the drama of the professional circuit in this 16-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barunba-japan', 'Turbografx-16', 'Barunba (Japan)', '1989', 'Platformer', 'Namco', '1', 'Action platformer', 'Multi-directional scrolling shooter with a focus on orb management.', 'Pilot a sphere-shaped craft and defend it from all directions.', 'A unique 360-degree shooter featuring diverse planets and power-ups.', 'Barunba (Japan) for TurboGrafx-16 is an innovative shmup. Rotate your shield and fire in any direction to survive intense alien encounters in this colorful classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-japan', 'Turbografx-16', 'Batman (Japan)', '1989', 'Action', 'Sunsoft', '1', 'Action platformer', 'Top-down action-adventure based on the 1989 film.', 'Navigate through Gotham City to defeat the Joker and his henchmen.', 'A Japan-exclusive Batman game that follows the movie''s plot closely.', 'Batman (Japan) on TurboGrafx-16 offers a unique top-down perspective on the Dark Knight''s quest. Collect items and navigate mazes in this visually sharp movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-ace-japan', 'Turbografx-16', 'Battle Ace (Japan)', '1989', 'Shooter', 'Hudson Soft', '1', 'Vertical sci-fi shooter', 'First-person 3D flight combat and exploration.', 'Pilot an advanced fighter through polygonal 3D arenas to destroy targets.', 'A technically ambitious SuperGrafx game featuring early 3D graphics.', 'Battle Ace (Japan) for TurboGrafx-16 showcases the power of the SuperGrafx hardware. Experience fluid movement and intense aerial combat in this rare 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-lode-runner-japan', 'Turbografx-16', 'Battle Lode Runner (Japan)', '1989', 'Puzzle', 'Hudson Soft', '1', 'Action puzzle game', 'Top-down grid-based puzzle game with cooperative play.', 'Dig holes to trap enemies and collect gold across various levels.', 'A massive and refined entry in the Lode Runner series with new features.', 'Battle Lode Runner (Japan) on TurboGrafx-16 offers addictive puzzle action. Master the level editor and compete with friends in this definitive version of the classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-royale-usa', 'Turbografx-16', 'Battle Royale (USA)', '1989', 'Fighting', 'Data East', '1', 'Arcade-style fighting', 'One-on-one professional wrestling simulation.', 'Defeat a roster of eccentric wrestlers to win the championship belt.', 'A hard-hitting sports game featuring large sprites and diverse moves.', 'Battle Royale (USA) for TurboGrafx-16 brings the excitement of the ring home. Utilize slams, pins, and power moves to dominate your rivals in this 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('be-ball-japan', 'Turbografx-16', 'Be Ball (Japan)', '1989', 'Puzzle', 'Naxat Soft', '1', 'Arcade puzzle action', 'Top-down action-puzzle game featuring colorful characters.', 'Place and kick balls to defeat enemies and solve level-based puzzles.', 'A cute and addictive puzzle game known as Chew Man Fu in the West.', 'Be Ball (Japan) on TurboGrafx-16 offers high-energy puzzle fun. Master the physics of the colored spheres to clear stages in this vibrant and charming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('benkei-gaiden-japan', 'Turbografx-16', 'Benkei Gaiden (Japan)', '1989', 'Action', 'Sigma Enterprises', '1', 'Japanese action RPG', 'Traditional turn-based Japanese RPG with historical themes.', 'Lead a party of warriors through medieval Japan to defeat evil spirits.', 'A deep JRPG featuring impressive art and a classic combat system.', 'Benkei Gaiden (Japan) for TurboGrafx-16 is a hidden gem for RPG fans. Experience a mature narrative based on Japanese folklore with a beautiful 16-bit presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bikkuriman-world-japan', 'Turbografx-16', 'Bikkuriman World (Japan)', '1989', 'Platformer', 'Hudson Soft', '1', 'Wonder Boy–style platformer', 'Side-scrolling action-RPG with a focus on equipment and upgrades.', 'Navigate a fantasy world to defeat monsters and rescue the land.', 'An enhanced version of Wonder Boy in Monster Land with unique characters.', 'Bikkuriman World (Japan) on TurboGrafx-16 offers addictive action-RPG gameplay. Upgrade your gear and explore diverse environments in this early system masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bikkuriman-world-japan-en-by-demiforce-v10', 'Turbografx-16', 'Bikkuriman World (Japan) [En by Demiforce v1.0]', '1989', 'Platformer', 'Hudson Soft', '1', 'Wonder Boy–style platformer', 'Side-scrolling action-RPG with translated dialogue.', 'Explore the world of Bikkuriman with full English text and story.', 'A fan-translated version of the action-RPG classic for Western players.', 'Bikkuriman World [En] allows English speakers to enjoy the deep Wonder Boy-style mechanics and lore of the Bikkuriman universe on the TurboGrafx-16.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazing-lazers-usa', 'Turbografx-16', 'Blazing Lazers (USA)', '1989', 'Shooter', 'Hudson Soft', '1', 'Vertical arcade shooter', 'Vertical-scrolling shoot ''em up with a focus on weapon upgrades.', 'Pilot the Gunhed starship to destroy the Dark Force alien empire.', 'A technical masterpiece known for its massive bosses and fast action.', 'Blazing Lazers on TurboGrafx-16 is one of the system''s premier shooters. Experience incredible weapon power-ups and intense 16-bit action in this Hudson Soft classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blodia-japan', 'Turbografx-16', 'Blodia (Japan)', '1991', 'Puzzle', 'Hudson Soft', '1', 'Block-based puzzle action', 'Tile-sliding puzzle game with path-building mechanics.', 'Slide tiles to create a continuous track for a moving ball.', 'A polished puzzle title known as Timeball in the West.', 'Blodia (Japan) for TurboGrafx-16 offers brain-teasing strategy. Master the spatial puzzles and manage your time to complete increasingly complex 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bloody-wolf-usa', 'Turbografx-16', 'Bloody Wolf (USA)', '1989', 'Action', 'Data East', '1', 'Run-and-gun action', 'Side-scrolling "run and gun" military shooter.', 'Infiltrate enemy territory to rescue the President and destroy a rogue army.', 'A high-energy action port of the arcade hit with diverse weaponry.', 'Bloody Wolf (USA) on TurboGrafx-16 delivers explosive combat and a surprising story. Fight through jungles and bases in this definitive 16-bit military brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('body-conquest-ii-japan', 'Turbografx-16', 'Body Conquest II (Japan)', '1991', 'Action', 'Quest', '1', 'Japanese adventure action', 'Digital board game and RPG hybrid with adult-themed visuals.', 'Defeat opponents in tactical combat to reveal digitized rewards.', 'A Japan-exclusive adult RPG featuring anime-style art and combat.', 'Body Conquest II (Japan) for TurboGrafx-16 is a rare mature-themed title. Experience a blend of strategy and visual novel elements in this unique 16-bit Japanese import.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman---users-battle-japan', 'Turbografx-16', 'Bomberman - Users Battle (Japan)', '1993', 'Action', 'Hudson Soft', '1-5', 'Multiplayer bomber action', 'Top-down grid-based action maze game.', 'Compete in multiplayer battles to be the last Bomberman standing.', 'A specialized version of Bomberman focused entirely on the battle mode.', 'Bomberman: Users Battle (Japan) on TurboGrafx-16 is the ultimate party experience. Challenge friends in intense 16-bit arenas designed for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-93-japan', 'Turbografx-16', 'Bomberman ''93 (Japan)', '1992', 'Action', 'Hudson Soft', '1-5', 'Multiplayer bomber action', 'Top-down grid-based action and puzzle-adventure.', 'Use bombs to clear obstacles and defeat enemies across various planets.', 'A landmark entry in the series featuring a deep campaign and 5-player mode.', 'Bomberman ''93 (Japan) for TurboGrafx-16 sets the standard for the franchise. Experience vibrant 16-bit worlds and addictive multiplayer action in this genre-defining hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-93-japan-special-version', 'Turbografx-16', 'Bomberman ''93 (Japan) (Special Version)', '1992', 'Action', 'Hudson Soft', '1-5', 'Multiplayer bomber action', 'Top-down grid-based action (promotional/tournament version).', 'Compete for high scores in a timed version of the classic maze game.', 'A rare special edition used for promotional events in Japan.', 'Bomberman ''93 (Special Version) is a collector''s dream for the PC Engine. Experience optimized competitive gameplay in this rare 16-bit tournament edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-93-usa', 'Turbografx-16', 'Bomberman ''93 (USA)', '1993', 'Action', 'Hudson Soft', '1-5', 'Multiplayer bomber action', 'Top-down grid-based action and puzzle-adventure.', 'Use bombs to clear obstacles and defeat enemies across various planets.', 'The North American release of the highly acclaimed 16-bit sequel.', 'Bomberman ''93 (USA) on TurboGrafx-16 delivers hours of single-player and multiplayer fun. Master the power-ups and outsmart your rivals in this essential action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-94-japan', 'Turbografx-16', 'Bomberman ''94 (Japan)', '1993', 'Action', 'Hudson Soft', '1-5', 'Multiplayer bomber action', 'Top-down grid-based action with new mechanics.', 'Recover the stars of the world by clearing stages and defeating bosses.', 'Often considered the best game in the series on the 16-bit platform.', 'Bomberman ''94 (Japan) for TurboGrafx-16 introduces rideable creatures (Louies). Experience the peak of 16-bit Bomberman with incredible graphics and refined mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-japan', 'Turbografx-16', 'Bomberman (Japan)', '1988', 'Action', 'Hudson Soft', '1-2', 'Classic bomber action', 'Top-down grid-based action maze game.', 'Navigate through mazes and defeat the Black Bomberman''s forces.', 'The game that launched the series'' popularity on 16-bit hardware.', 'Bomberman (Japan) on TurboGrafx-16 features the first appearance of the legendary battle mode. Experience the pure, addictive origins of the 16-bit bomb-dropping phenomenon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-usa', 'Turbografx-16', 'Bomberman (USA)', '1990', 'Action', 'Hudson Soft', '1-2', 'Classic bomber action', 'Top-down grid-based action maze game.', 'Navigate through mazes and defeat the Black Bomberman''s forces.', 'The North American debut of the legendary puzzle-action franchise.', 'Bomberman (USA) for TurboGrafx-16 is a foundational title for the system. Blast through 50 stages and engage in frantic 5-player multiplayer battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonk-iii---bonks-big-adventure-usa', 'Turbografx-16', 'Bonk III - Bonk''s Big Adventure (USA)', '1993', 'Platformer', 'Hudson Soft', '1', 'Prehistoric cartoon platformer', 'Side-scrolling platformer with size-changing mechanics.', 'Use your head-butt attacks to defeat enemies and save the world.', 'The third entry featuring a cooperative mode and growth power-ups.', 'Bonk III: Bonk''s Big Adventure (USA) on TurboGrafx-16 adds a unique twist with shrinking and growing candies. Experience massive 16-bit bosses in this fun platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonks-adventure-usa', 'Turbografx-16', 'Bonk''s Adventure (USA)', '1989', 'Platformer', 'Hudson Soft', '1', 'Prehistoric cartoon platformer', 'Side-scrolling platformer with a focus on head-butt combat.', 'Journey through prehistoric lands to rescue Princess Za.', 'The iconic debut of the system''s mascot with unique mechanics.', 'Bonk''s Adventure (USA) for TurboGrafx-16 is a platforming masterpiece. Use Bonk’s powerful head to climb, spin, and smash through a vibrant prehistoric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonks-revenge-usa', 'Turbografx-16', 'Bonk''s Revenge (USA)', '1991', 'Platformer', 'Hudson Soft', '1', 'Prehistoric cartoon platformer', 'Side-scrolling platformer featuring multiple transformations.', 'Defeat King Drool to reclaim the Moon and save the prehistoric world.', 'A highly polished sequel with improved graphics and diverse levels.', 'Bonk''s Revenge (USA) on TurboGrafx-16 is a fan favorite. Experience more transformations and refined 16-bit gameplay in this definitive mascot platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-danshaku-don---the-lost-sunheart-japan', 'Turbografx-16', 'Bouken Danshaku Don - The Lost Sunheart (Japan)', '1992', 'Action', 'Irem', '1', 'Action adventure platformer', 'Side-scrolling horizontal shoot ''em up with a unique style.', 'Pilot a flying vessel to recover the lost Sunheart across weird worlds.', 'A quirky and visually distinct shmup with humorous character designs.', 'Bouken Danshaku Don (Japan) for TurboGrafx-16 offers a surreal shooting experience. Navigate through bizarre levels with creative 16-bit sprite work and fast action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boxyboy-usa', 'Turbografx-16', 'Boxyboy (USA)', '1990', 'Puzzle', 'Atlus', '1', 'Box-pushing puzzle game', 'Isometric block-pushing puzzle game.', 'Move crates to designated locations within a warehouse.', 'A challenging port of the classic Sokoban puzzle series.', 'Boxyboy (USA) on TurboGrafx-16 tests your logic and planning. Solve over 250 puzzles in this clean and addictive 16-bit brain-teaser.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bravoman-usa', 'Turbografx-16', 'Bravoman (USA)', '1990', 'Action', 'Namco', '1', 'Comedic superhero action', 'Side-scrolling martial arts action with superhero themes.', 'Transform into a powerful hero to defeat the evil Dr. Bomb.', 'A port of the Namco arcade hit featuring humorous storytelling.', 'Bravoman (USA) for TurboGrafx-16 is a unique brawler with stretchy limb attacks. Experience the quirky 16-bit charm and challenging boss fights of this arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('break-in-japan', 'Turbografx-16', 'Break In (Japan)', '1989', 'Sports', 'Naxat Soft', '1', 'Japanese pool simulation', 'First-person perspective billiards (pool) simulation.', 'Compete in various pool games to become the table master.', 'A realistic and polished pool sim with smooth ball physics.', 'Break In (Japan) on TurboGrafx-16 offers a sophisticated billiards experience. Master your aim and spin in this high-quality 16-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubblegum-crash!---knight-sabers-2034-japan', 'Turbografx-16', 'Bubblegum Crash! - Knight Sabers 2034 (Japan)', '1991', 'Adventure', 'Artmic', '1', 'Anime sci-fi adventure', 'Visual novel and adventure game based on the anime series.', 'Lead the Knight Sabers through a cybernetic mystery in Mega Tokyo.', 'A deep adventure game featuring high-quality anime art and voice-like text.', 'Bubblegum Crash! (Japan) for TurboGrafx-16 is a treat for fans of the OVA. Solve cases and interact with iconic characters in this detailed 16-bit sci-fi quest.');
