INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burning-angels-japan', 'Turbografx-16', 'Burning Angels (Japan)', '1990', 'Shooter', 'Naxat Soft', '1', 'Vertical sci-fi shooter', 'Vertical-scrolling shoot ''em up featuring female protagonists.', 'Pilot a high-tech fighter to defend the kingdom from an invading fleet.', 'A visually vibrant shooter with a focus on anime-style characters.', 'Burning Angels (Japan) for TurboGrafx-16 offers fast-paced 16-bit shmup action. Experience impressive power-ups and detailed backgrounds in this rare Japanese import.');
