INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cadash-japan', 'Turbografx-16', 'Cadash (Japan)', '1991', 'Action', 'Taito', '1', 'Action RPG platformer', 'Side-scrolling action-RPG with multiple character classes.', 'Journey through a dark fantasy world to defeat the demon Balrog.', 'A landmark arcade port featuring experience points and equipment.', 'Cadash (Japan) for TurboGrafx-16 is a deep and atmospheric adventure. Choose between a Fighter, Mage, Priest, or Ninja in this classic 16-bit RPG-platformer hybrid.');
