INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-pro-wrestling-3---legend-bout-japan', 'Turbografx-16', 'Fire Pro Wrestling 3 - Legend Bout (Japan)', '1993', 'Wrestling', 'Human Entertainment', '1-2', 'Japanese pro wrestling', 'One-on-one professional wrestling with legendary themes.', 'Compete against legends of the ring in the ultimate wrestling showdown.', 'The third entry in the series featuring the most refined 16-bit engine.', 'Fire Pro Wrestling 3 (Japan) on TurboGrafx-16 is the pinnacle of the series'' early years. Master technical wrestling in this deep and highly-respected 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formation-soccer---human-cup-90-japan', 'Turbografx-16', 'Formation Soccer - Human Cup ''90 (Japan)', '1990', 'Sports', 'Human Entertainment', '1-2', 'Arcade soccer', 'Top-down soccer simulation with a focus on positioning.', 'Lead your team to victory in the international Human Cup tournament.', 'A fast-paced soccer game that debuted the popular Formation series.', 'Formation Soccer - Human Cup ''90 (Japan) on TurboGrafx-16 offers fluid 16-bit football action. Master the team formations and quick passing to dominate the world stage.');
