INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chan-japan', 'Turbografx-16', 'Jackie Chan (Japan)', '1988', 'Action', 'Hudson Soft', '1', 'Action platformer', 'Side-scrolling martial arts platformer with anime-style art.', 'Fight through various stages to defeat a mysterious sorcerer.', 'A highly-regarded action game featuring the likeness of Jackie Chan.', 'Jackie Chan (Japan) on TurboGrafx-16 is a masterpiece of fluid animation. Execute powerful combos and special moves in this vibrant and charming 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chans-action-kung-fu-usa', 'Turbografx-16', 'Jackie Chan''s Action Kung Fu (USA)', '1990', 'Action', 'Hudson Soft', '1', 'Action platformer', 'Side-scrolling martial arts platformer with anime-style art.', 'Defeat the Prince of Sorcerers and rescue your sister.', 'The acclaimed North American version of the Jackie Chan action game.', 'Jackie Chan''s Action Kung Fu (USA) for TurboGrafx-16 offers top-tier platforming. Master the 16-bit martial arts moves and tackle inventive bosses in this essential classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigoku-meguri-japan', 'Turbografx-16', 'Jigoku Meguri (Japan)', '1989', 'Action', 'Hudson Soft', '1', 'Horror action platformer', 'Side-scrolling action-platformer set in the Japanese afterlife.', 'Navigate through various hellish realms to defeat demons and monsters.', 'A colorful port of the Taito arcade hit known as Bonze Adventure.', 'Jigoku Meguri (Japan) on TurboGrafx-16 features unique folklore-based enemies. Battle through the 16-bit underworld in this atmospheric and challenging action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinmu-denshou-japan', 'Turbografx-16', 'Jinmu Denshou (Japan)', '1989', 'RPG', 'Nihon Telenet', '1', 'Fantasy action RPG', 'Vertical-scrolling action-shooter with mythological themes.', 'Fly through ancient landscapes and destroy enemy spirits and beasts.', 'A fast-paced and visually distinct shooter featuring a flying warrior.', 'Jinmu Denshou (Japan) for TurboGrafx-16 offers a unique mythological shooting experience. Master the divine attacks in this rare and artistic 16-bit vertical shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuouki-japan', 'Turbografx-16', 'Juuouki (Japan)', '1989', 'Action', 'Wave Corporation', '1', 'Arcade action platformer', 'Side-scrolling brawler with character transformation mechanics.', 'Fight through hordes of mythical beasts to rescue Athena.', 'A faithful port of Sega''s legendary arcade hit, Altered Beast.', 'Juuouki (Japan) on TurboGrafx-16 brings the "Rise from your grave" action home. Collect spirit orbs to transform into powerful beasts in this iconic 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaizou-choujin-shubibinman-japan', 'Turbografx-16', 'Kaizou Choujin Shubibinman (Japan)', '1989', 'Action', 'Masaya', '1', 'Superhero action platformer', 'Side-scrolling action-platformer with melee and ranged combat.', 'Defeat a robotic army as an enhanced "Cyber-Man" hero.', 'A cult classic brawler featuring a mix of swordplay and energy blasts.', 'Kaizou Choujin Shubibinman (Japan) for TurboGrafx-16 delivers high-energy 16-bit action. Navigate mechanical stages and defeat huge bosses in this Sentai-inspired quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaizou-choujin-shubibinman-2---aratanaru-teki-japan', 'Turbografx-16', 'Kaizou Choujin Shubibinman 2 - Aratanaru Teki (Japan)', '1991', 'Action', 'Masaya', '1', 'Superhero action platformer', 'Side-scrolling action-platformer with shooter elements.', 'Save the world from a new robotic threat with enhanced powers.', 'A highly polished sequel with improved graphics and diverse levels.', 'Kaizou Choujin Shubibinman 2 (Japan) for TurboGrafx-16 is a fan favorite. Experience refined 16-bit combat and cinematic storytelling in this definitive action sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kato-chan-&-ken-chan-japan', 'Turbografx-16', 'Kato Chan & Ken Chan (Japan)', '1988', 'Action', 'Hudson Soft', '1', 'Comedic action platformer', 'Side-scrolling platformer based on the famous variety show.', 'Survive a series of wacky trials and traps set by your co-host.', 'The legendary and humorous Japanese original version of J.J. & Jeff.', 'Kato Chan & Ken Chan (Japan) for TurboGrafx-16 is famous for its slapstick comedy. Experience the original 16-bit toilet humor and challenging platforming of this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kattobi!-takuhai-kun-japan', 'Turbografx-16', 'Kattobi! Takuhai Kun (Japan)', '1989', 'Action', 'Atlus', '1', 'Arcade delivery action', 'Top-down driving and delivery action game.', 'Deliver packages across the city within the time limit.', 'A unique and quirky game where speed and navigation are key.', 'Kattobi! Takuhai Kun (Japan) on TurboGrafx-16 offers a fresh take on the driving genre. Master the city streets to become the ultimate delivery man in this colorful 16-bit sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keith-courage-in-alpha-zones-usa', 'Turbografx-16', 'Keith Courage in Alpha Zones (USA)', '1989', 'Action', 'Hudson Soft', '1', 'Action platform shooter', 'Side-scrolling action-platformer with mech transformations.', 'Transform into the powerful Nova Suit to defeat the alien Brawlers.', 'The system''s launch title in the USA, based on the Mashin Hero Wataru anime.', 'Keith Courage (USA) for TurboGrafx-16 is a cornerstone of the library. Experience the dual gameplay of exploring villages and battling through the 16-bit Alpha Zones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kickball-japan', 'Turbografx-16', 'KickBall (Japan)', '1990', 'Sports', 'Technosoft', '1', 'Dodgeball-style sports', 'Behind-the-back futuristic sports game.', 'Win high-speed kickball matches using specialized power moves.', 'A unique 16-bit blend of soccer and dodgeball with a sci-fi theme.', 'KickBall (Japan) on TurboGrafx-16 offers fast-paced and competitive sports action. Master the trajectory of the ball to dominate your opponents in this original title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiki-kaikai-japan', 'Turbografx-16', 'Kiki Kaikai (Japan)', '1988', 'Action', 'Taito', '1', 'Arcade action shooter', 'Fixed-screen action-shooter featuring a miko priestess.', 'Use paper charms and a purification rod to defeat spirits and monsters.', 'A beautiful and faithful port of Taito''s classic Pocky & Rocky series.', 'Kiki Kaikai (Japan) on TurboGrafx-16 delivers charming 16-bit supernatural action. Navigate through shrines and forests to banish the yokai in this essential classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-casino-japan', 'Turbografx-16', 'King of Casino (Japan)', '1989', 'Casino', 'Namco', '1', 'Casino gambling simulation', 'Multi-game gambling simulation with casino themes.', 'Build your fortune by winning at various high-stakes casino games.', 'Features Blackjack, Slot Machines, and more with a competitive twist.', 'King of Casino (Japan) for TurboGrafx-16 offers a polished gambling experience. Master the odds and manage your virtual credits in this detailed 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-casino-usa', 'Turbografx-16', 'King of Casino (USA)', '1989', 'Casino', 'Namco', '1', 'Casino gambling simulation', 'Multi-game gambling simulation with casino themes.', 'Build your fortune by winning at various high-stakes casino games.', 'The North American release of the comprehensive casino sim.', 'King of Casino (USA) on TurboGrafx-16 brings the Vegas atmosphere home. Test your luck across multiple 16-bit games in this competitive virtual gambling hall.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-japan', 'Turbografx-16', 'Klax (Japan)', '1990', 'Puzzle', 'Tengen', '1', 'Falling-block puzzle', 'Falling-block puzzle game with vertical matching.', 'Catch falling tiles and arrange them into rows to clear the board.', 'A perfect port of the Atari arcade hit with vibrant colors.', 'Klax (Japan) for TurboGrafx-16 provides timeless and addictive puzzle fun. Master the "catch and stack" mechanics in this polished 16-bit rendition of the classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-usa', 'Turbografx-16', 'Klax (USA)', '1990', 'Puzzle', 'Tengen', '1', 'Falling-block puzzle', 'Falling-block puzzle game with vertical matching.', 'Catch falling tiles and arrange them into rows to clear the board.', 'The acclaimed North American version of the arcade puzzle sensation.', 'Klax (USA) for TurboGrafx-16 is a masterclass in puzzle design. Test your reflexes and spatial logic in this essential and highly addictive 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knight-rider-special-japan', 'Turbografx-16', 'Knight Rider Special (Japan)', '1989', 'Action', 'Pack-In-Video', '1', 'TV tie-in action', 'Behind-the-back pseudo-3D driving and combat game.', 'Pilot K.I.T.T. through various missions to stop criminal organizations.', 'A Japan-exclusive title based on the hit 80s TV series.', 'Knight Rider Special (Japan) on TurboGrafx-16 delivers high-speed action. Use K.I.T.T.''s gadgets and turbo boost to defeat enemies in this polished 16-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kore-ga-pro-yakyuu-89-japan', 'Turbografx-16', 'Kore ga Pro Yakyuu ''89 (Japan)', '1989', 'Sports', 'Sega', '1', 'Baseball simulation', 'Traditional overhead baseball simulation.', 'Lead your chosen Japanese team to the pennant championship.', 'A detailed sports title with updated 1989 rosters and stats.', 'Kore ga Pro Yakyuu ''89 (Japan) for TurboGrafx-16 offers authentic 16-bit baseball. Master the pitching and batting in this early but solid Japanese sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kore-ga-pro-yakyuu-90-japan', 'Turbografx-16', 'Kore ga Pro Yakyuu ''90 (Japan)', '1990', 'Sports', 'Sega', '1', 'Baseball simulation', 'Traditional overhead baseball simulation with updated stats.', 'Compete in the 1990 season with refined mechanics and visuals.', 'An improved sequel featuring better animation and deeper management.', 'Kore ga Pro Yakyuu ''90 (Japan) on TurboGrafx-16 is a premier baseball simulation. Experience the thrill of the Japanese league in this polished 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-fu-the-japan', 'Turbografx-16', 'Kung Fu, The (Japan)', '1987', 'Action', 'Irem', '1', 'Classic martial arts action', 'Side-scrolling martial arts brawler with giant sprites.', 'Walk through stages while punching and kicking waves of enemies.', 'The original Japanese version of the game known as China Warrior.', 'Kung Fu, The (Japan) for TurboGrafx-16 is a visual showcase of early PC Engine power. Experience high-impact 16-bit combat with massive character models.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuukyoku-mahjong---idol-graphics-japan', 'Turbografx-16', 'Kyuukyoku Mahjong - Idol Graphics (Japan)', '1989', 'Mahjong', 'Naxat Soft', '1', 'Strip mahjong game', 'Digital Mahjong simulation with idol-themed visuals.', 'Win Mahjong hands to unlock digitized graphics of various idols.', 'A rare Japan-exclusive gambling game featuring high-quality graphics.', 'Kyuukyoku Mahjong: Idol Graphics on TurboGrafx-16 offers a mature-themed board game experience. Master the tiles to reveal the 16-bit rewards in this rare title.');
