INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kyuukyoku-tiger-japan', 'Turbografx-16', 'Kyuukyoku Tiger (Japan)', '1989', 'Shooter', 'Toaplan', '1', 'Vertical arcade shooter', 'Vertical-scrolling shoot ''em up with massive firepower.', 'Pilot the Tiger-Heli to destroy the invading alien fleet.', 'A legendary port of the Toaplan arcade hit known as Twin Cobra.', 'Kyuukyoku Tiger (Japan) on TurboGrafx-16 is a pinnacle of the shmup genre. Master the powerful spread-shot and bombs in this definitive 16-bit vertical shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lady-sword-japan', 'Turbografx-16', 'Lady Sword (Japan)', '1988', 'Action', 'Hudson Soft', '1', 'Fantasy action platformer', 'First-person dungeon crawler with turn-based combat.', 'Explore a cursed tower to find the legendary Lady Sword.', 'A dark and atmospheric RPG with anime-style character designs.', 'Lady Sword (Japan) on TurboGrafx-16 offers a classic grid-based dungeon crawling experience. Navigate lethal traps and battle monstrous foes in this rare 16-bit Japanese JRPG.');
