INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legendary-axe-ii-the-usa', 'Turbografx-16', 'Legendary Axe II, The (USA)', '1990', 'Action', 'Victor Musical Industries', '1', 'Action platformer sequel', 'Side-scrolling action-brawler with dark fantasy themes.', 'Battle through a demonic realm to reclaim your throne.', 'A gritty sequel with atmospheric visuals and multiple weapon types.', 'The Legendary Axe II (USA) for TurboGrafx-16 offers a darker tone than the original. Master the sword and axe to conquer the 16-bit underworld in this intense action quest.');
