INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-shikyaku-retsuden---mahjong-wars-japan', 'Turbografx-16', 'Mahjong Shikyaku Retsuden - Mahjong Wars (Japan)', '1991', 'Mahjong', 'Naxat Soft', '1', 'Mahjong strategy', 'Narrative-driven Mahjong simulation.', 'Experience a story of rivalry and high-stakes gambling through Mahjong.', 'A unique blend of adventure elements and traditional board gameplay.', 'Mahjong Shikyaku Retsuden (Japan) on TurboGrafx-16 delivers a cinematic Mahjong experience. Follow the drama and master the tiles in this 16-bit Japanese quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maison-ikkoku-japan', 'Turbografx-16', 'Maison Ikkoku (Japan)', '1989', 'Adventure', 'Micro Cabin', '1', 'Romantic visual novel', 'Visual novel and adventure game based on the hit manga.', 'Navigate life and romance at the Ikkoku Kan apartment boarding house.', 'A beautiful adventure game with art reflecting Rumiko Takahashi’s style.', 'Maison Ikkoku (Japan) for TurboGrafx-16 is a treat for fans of the classic anime. Interact with Kyoko and Godai in this detailed 16-bit romantic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maison-ikkoku-japan-en-by-dave-shadoff+filler-v101', 'Turbografx-16', 'Maison Ikkoku (Japan) [En by Dave Shadoff+Filler v1.01]', '1989', 'Adventure', 'Micro Cabin', '1', 'Romantic visual novel', 'Visual novel and adventure game with translated dialogue.', 'Experience the romance of Ikkoku Kan with full English text.', 'A fan-translated version of the iconic manga-based adventure game.', 'Maison Ikkoku [En] on TurboGrafx-16 allows English speakers to enjoy the charming story and humor of the series in this polished 16-bit visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majin-eiyuu-den-wataru-japan', 'Turbografx-16', 'Majin Eiyuu Den Wataru (Japan)', '1989', 'Action', 'Hudson Soft', '1', 'Anime action platformer', 'Side-scrolling action-platformer based on the anime.', 'Pilot the robotic Ryujinmaru to save the colorful realm of Soukaizan.', 'The Japanese original of the game known as Keith Courage in the West.', 'Majin Eiyuu Den Wataru (Japan) for TurboGrafx-16 is a vibrant anime tie-in. Experience high-energy 16-bit brawling and transformations in this classic PC Engine title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makai-hakken-den-shada-japan', 'Turbografx-16', 'Makai Hakken Den Shada (Japan)', '1989', 'RPG', 'Nihon Falcom', '1', 'Fantasy action RPG', 'Overhead action-RPG with a focus on dungeon exploration.', 'Journey through a dark fantasy world to stop an ancient evil.', 'A deep and challenging RPG featuring real-time combat and puzzles.', 'Makai Hakken Den Shada (Japan) on TurboGrafx-16 offers an expansive 16-bit adventure. Master your skills and uncover secrets in this atmospheric Japanese quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makai-prince-dorabocchan-japan', 'Turbografx-16', 'Makai Prince Dorabocchan (Japan)', '1990', 'Action', 'Namco', '1', 'Comedic platform action', 'Side-scrolling action-platformer featuring a young vampire.', 'Reclaim your throne from the usurpers across spooky levels.', 'A charming and fun platformer known as "The Kung Fu''s" successor.', 'Makai Prince Dorabocchan (Japan) for TurboGrafx-16 is a hidden gem. Navigate through creative horror-themed levels in this vibrant and polished 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('makyou-densetsu-japan', 'Turbografx-16', 'Makyou Densetsu (Japan)', '1988', 'Action', 'Hudson Soft', '1', 'Horror-themed action platformer', 'Side-scrolling action-platformer with giant sprites.', 'Walk through stages while punching and kicking waves of enemies.', 'The Japanese title for the visual spectacle known as China Warrior.', 'Makyou Densetsu (Japan) on TurboGrafx-16 showcases the system''s early sprite-pushing power. Experience high-impact 16-bit combat with massive character models.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maniac-puroresu---asu-heno-tatakai-japan', 'Turbografx-16', 'Maniac Puroresu - Asu heno Tatakai (Japan)', '1989', 'Wrestling', 'Human Entertainment', '1-2', 'Arcade pro wrestling', 'Pro-wrestling simulation and career management.', 'Rise from an amateur to a wrestling legend through hard-hitting matches.', 'Features a unique "story" focus and tactical grappling mechanics.', 'Maniac Puroresu (Japan) for TurboGrafx-16 offers an authentic Japanese wrestling experience. Master the timing and build your career in this deep 16-bit sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mesopotamia-japan', 'Turbografx-16', 'Mesopotamia (Japan)', '1991', 'Shooter', 'Atlus', '1', 'Vertical sci-fi shooter', 'Multi-directional scrolling action-puzzle game.', 'Maneuver a bouncing ball through complex mazes using physics.', 'A unique and difficult title that tests your momentum control.', 'Mesopotamia (Japan) on TurboGrafx-16 is a true original. Master the bouncing mechanics and navigate hazard-filled 16-bit stages in this innovative puzzle-action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-stoker-japan', 'Turbografx-16', 'Metal Stoker (Japan)', '1991', 'Shooter', 'Face', '1', 'Advanced vertical shooter', 'Vertical-scrolling tank combat and shooting.', 'Pilot a high-tech armored vehicle to clear waves of robotic enemies.', 'A fast-paced shooter featuring multi-directional fire and upgrades.', 'Metal Stoker (Japan) for TurboGrafx-16 delivers intense vehicular combat. Experience fluid 16-bit shooting and massive bosses in this polished mechanical shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('military-madness-usa', 'Turbografx-16', 'Military Madness (USA)', '1989', 'Strategy', 'Hudson Soft', '1', 'Turn-based military strategy', 'Hex-based tactical strategy set on the Moon.', 'Lead the Union forces to defeat the Axis Empire in a lunar war.', 'One of the most highly-respected strategy games of the 16-bit era.', 'Military Madness (USA) on TurboGrafx-16 is a masterclass in tactical design. Master the "Zone of Control" and unit positioning in this essential 16-bit strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mizubaku-dai-bouken-japan', 'Turbografx-16', 'Mizubaku Dai Bouken (Japan)', '1990', 'Action', 'Hudson Soft', '1', 'Cute action platformer', 'Side-scrolling platformer with liquid-based weapons.', 'Use water bombs to defeat enemies and extinguish fires.', 'A gorgeous port of the Liquid Kids arcade hit with fluid animation.', 'Mizubaku Dai Bouken (Japan) for TurboGrafx-16 is a visual delight. Experience charming character designs and creative 16-bit platforming in this Taito classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-densetsu-gaiden-dai-1-shuu-japan', 'Turbografx-16', 'Momotarou Densetsu Gaiden Dai 1 Shuu (Japan)', '1990', 'RPG', 'Hudson Soft', '1', 'Comedy role-playing game', 'Turn-based JRPG spin-off with tactical elements.', 'Journey through Japanese folklore-inspired lands as the peach boy.', 'A deep and humorous RPG featuring iconic characters from the series.', 'Momotarou Densetsu Gaiden (Japan) for TurboGrafx-16 offers a fresh take on the folklore. Experience polished 16-bit turn-based combat in this charming Japanese quest.');
