INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-densetsu-turbo-japan', 'Turbografx-16', 'Momotarou Densetsu Turbo (Japan)', '1989', 'RPG', 'Hudson Soft', '1', 'Comedy role-playing game', 'Turn-based JRPG with enhanced speed and visuals.', 'Embark on the original quest of Momotarou with 16-bit refinements.', 'A "Turbo" version of the classic quest with faster pacing and better art.', 'Momotarou Densetsu Turbo (Japan) for TurboGrafx-16 is the definitive way to play the first entry. Master the traditional 16-bit combat in this beloved folklore adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-katsugeki-japan', 'Turbografx-16', 'Momotarou Katsugeki (Japan)', '1991', 'Action', 'Hudson Soft', '1', 'Action sports platformer', 'Side-scrolling action-platformer featuring Momotarou.', 'Use special items and skills to battle through a demon-infested land.', 'An action-oriented spin-off of the popular RPG series.', 'Momotarou Katsugeki (Japan) on TurboGrafx-16 offers fast-paced 16-bit platforming. Explore vibrant levels and defeat creative bosses in this polished folklore quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-puroresu-japan', 'Turbografx-16', 'Monster Puroresu (Japan)', '1991', 'Wrestling', 'Human Entertainment', '1-2', 'Fantasy pro wrestling', 'One-on-one monster wrestling simulation.', 'Select a monstrous fighter and win the intergalactic championship.', 'A unique and humorous take on pro-wrestling with creature designs.', 'Monster Puroresu (Japan) for TurboGrafx-16 delivers over-the-top ring action. Master the specialized moves of each beast in this quirky 16-bit sports brawler.');
