INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-roader-japan', 'Turbografx-16', 'Moto Roader (Japan)', '1989', 'Racing', 'Hudson Soft', '1-4', 'Top-down arcade racing', 'Top-down futuristic racing with 5-player support.', 'Finish first in high-speed races using points to upgrade your car.', 'A classic party racer known for its intense local multiplayer action.', 'Moto Roader (Japan) on TurboGrafx-16 is a definitive multiplayer experience. Customize your vehicle and outmaneuver friends in this high-octane 16-bit futuristic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-roader-usa', 'Turbografx-16', 'Moto Roader (USA)', '1989', 'Racing', 'Hudson Soft', '1-4', 'Top-down arcade racing', 'Top-down futuristic racing with 5-player support.', 'Finish first in high-speed races using points to upgrade your car.', 'The North American release of the frantic Hudson Soft racer.', 'Moto Roader (USA) for TurboGrafx-16 brings competitive racing to the living room. Use nitro boosts and tactical upgrades to dominate the 16-bit track.');
