INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-heli-no-daibouken-japan', 'Turbografx-16', 'Mr. Heli no Daibouken (Japan)', '1989', 'Shooter', 'Irem', '1', 'Cute side-scrolling shooter', 'Horizontal-scrolling shoot ''em up with physics elements.', 'Pilot a combat helicopter to destroy an alien threat and save the world.', 'A charming and difficult Irem arcade port with unique mechanical twists.', 'Mr. Heli no Daibouken (Japan) for TurboGrafx-16 is a quirky and detailed shmup. Use your rotors and bombs to navigate hazard-filled 16-bit levels in this classic arcade hit.');
