INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-no-mascarade-japan', 'Turbografx-16', 'Nazo no Mascarade (Japan)', '1988', 'Action', 'Namco', '1', 'Fantasy maze action', 'Visual novel and mystery adventure game.', 'Solve a complex mystery through dialogue and clue-finding.', 'A stylized adventure game with unique anime-style character art.', 'Nazo no Mascarade (Japan) for TurboGrafx-16 is an intriguing 16-bit investigation. Navigate the narrative and uncover the truth in this rare Japanese adventure title.');
