INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-ryuuken-den-japan', 'Turbografx-16', 'Ninja Ryuuken Den (Japan)', '1989', 'Action', 'Tecmo', '1', 'Ninja action platformer', 'Side-scrolling action-platformer with cinematic storytelling.', 'Avenge your father and defeat the Jaquio in this 16-bit remake.', 'An enhanced version of the NES classic with improved graphics and music.', 'Ninja Ryuuken Den (Japan) for TurboGrafx-16 is the ultimate way to play Ninja Gaiden. Experience the legendary difficulty with beautiful 16-bit visuals and sounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-spirit-usa', 'Turbografx-16', 'Ninja Spirit (USA)', '1989', 'Action', 'Irem', '1', 'Run-and-gun arcade action', 'Side-scrolling action-platformer with shadow clones.', 'Journey through a dark world to rescue your sister from a demonic cult.', 'Widely considered one of the best action games on the entire platform.', 'Ninja Spirit (USA) on TurboGrafx-16 is a technical and mechanical masterpiece. Master four distinct weapons in this atmospheric and high-speed 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-warriors-the-japan', 'Turbografx-16', 'Ninja Warriors, The (Japan)', '1988', 'Action', 'Natsume', '1', 'Cinematic action platformer', 'Side-scrolling beat ''em up with cybernetic ninjas.', 'Fight through the streets to assassinate a corrupt dictator.', 'A faithful port of Taito’s wide-screen arcade hit with great music.', 'The Ninja Warriors (Japan) for TurboGrafx-16 delivers high-impact cybernetic combat. Master your blades and survive waves of enemies in this gritty 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obocchama-kun-japan', 'Turbografx-16', 'Obocchama Kun (Japan)', '1989', 'Action', 'Tom Create', '1', 'Comedy anime platformer', 'Side-scrolling action and mini-game collection.', 'Navigate the wealthy world of Obocchama Kun in various wacky stages.', 'A humorous and colorful game based on the popular manga series.', 'Obocchama Kun (Japan) on TurboGrafx-16 offers quirky 16-bit fun. Experience the bizarre humor and diverse gameplay of this unique Japanese import.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-wolf-japan', 'Turbografx-16', 'Operation Wolf (Japan)', '1989', 'Shooter', 'Taito', '1', 'Light-gun arcade shooter', 'First-person light-gun style shooter.', 'Infiltrate enemy camps to rescue hostages across multiple missions.', 'A fast-paced and challenging port of the Taito arcade shooter.', 'Operation Wolf (Japan) for TurboGrafx-16 brings the intense arcade action home. Master your ammo and grenades to survive this classic 16-bit military blast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('order-of-the-griffon-usa', 'Turbografx-16', 'Order of the Griffon (USA)', '1992', 'RPG', 'Westwood Studios', '1', 'Western fantasy RPG', 'Turn-based tactical RPG set in the D&D universe.', 'Lead a party of adventurers through the Savage Frontier.', 'A sophisticated RPG featuring deep Dungeons & Dragons mechanics.', 'Order of the Griffon (USA) on TurboGrafx-16 offers a serious D&D challenge. Customize your heroes and explore a dangerous 16-bit fantasy realm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ordyne-japan', 'Turbografx-16', 'Ordyne (Japan)', '1988', 'Shooter', 'Namco', '1', 'Cute vertical shooter', 'Horizontal-scrolling "cute ''em up" with a shop system.', 'Pilot a flying machine to clear enemy forces in vibrant worlds.', 'A colorful and perfect port of Namco’s high-energy arcade shooter.', 'Ordyne (Japan) for TurboGrafx-16 is a visual delight. Collect crystals to buy powerful weapon upgrades in this charming and frantic 16-bit shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ordyne-usa', 'Turbografx-16', 'Ordyne (USA)', '1988', 'Shooter', 'Namco', '1', 'Cute vertical shooter', 'Horizontal-scrolling "cute ''em up" with a shop system.', 'Pilot a flying machine to clear enemy forces in vibrant worlds.', 'The North American release of the vibrant Namco arcade classic.', 'Ordyne (USA) for TurboGrafx-16 delivers high-speed shooting fun. Experience the incredible 16-bit graphics and creative bosses in this essential shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-live-japan', 'Turbografx-16', 'Out Live (Japan)', '1989', 'Shooter', 'Sunsoft', '1', 'Dark sci-fi vertical shooter', 'First-person 3D dungeon crawler with mecha combat.', 'Navigate through 3D labyrinths and battle enemy robots in real-time.', 'An ambitious and technically impressive early 3D mecha RPG.', 'Out Live (Japan) on TurboGrafx-16 offers an immersive sci-fi experience. Upgrade your robot and survive the lethal corridors in this unique 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-japan', 'Turbografx-16', 'Out Run (Japan)', '1989', 'Racing', 'Sega', '1-2', 'Arcade driving racer', 'Behind-the-back pseudo-3D arcade racing.', 'Race across various scenic routes with your girlfriend in a Ferrari.', 'An incredible port of Sega’s legend with vibrant colors and great music.', 'Out Run (Japan) for TurboGrafx-16 is a definitive way to enjoy the classic. Experience the smooth 16-bit scaling and iconic soundtrack in this premier racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('override-japan', 'Turbografx-16', 'Override (Japan)', '1989', 'Shooter', 'Naxat Soft', '1', 'Top-down sci-fi shooter', 'Vertical-scrolling shoot ''em up with high-speed action.', 'Pilot a high-tech fighter to stop an intergalactic threat.', 'A fast and polished shooter featuring impressive weapon power-ups.', 'Override (Japan) on TurboGrafx-16 delivers pure 16-bit shmup intensity. Master the firing patterns to survive massive bosses in this hidden gem of the library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('p-47---the-freedom-fighter-japan', 'Turbografx-16', 'P-47 - The Freedom Fighter (Japan)', '1988', 'Shooter', 'Jaleco', '1', 'Classic WWII vertical shooter', 'Horizontal-scrolling shoot ''em up with WWII themes.', 'Pilot a P-47 Thunderbolt to destroy the forces of the Axis.', 'A faithful arcade port featuring intense dogfights and massive bombers.', 'P-47: The Freedom Fighter (Japan) on TurboGrafx-16 delivers high-octane 16-bit aerial combat. Master your weaponry to survive relentless waves of tanks and planes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-land-japan', 'Turbografx-16', 'Pac-Land (Japan)', '1989', 'Platformer', 'Namco', '1', 'Colorful arcade platformer', 'Side-scrolling platformer based on the Pac-Man spinoff.', 'Journey through various lands to return a lost fairy to its home.', 'A colorful and unique platformer featuring Pac-Man with legs and arms.', 'Pac-Land (Japan) for TurboGrafx-16 captures the whimsical charm of the arcade. Navigate hidden secrets and tricky jumps in this vibrant 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-land-usa', 'Turbografx-16', 'Pac-Land (USA)', '1989', 'Platformer', 'Namco', '1', 'Colorful arcade platformer', 'Side-scrolling platformer based on the Pac-Man spinoff.', 'Journey through various lands to return a lost fairy to its home.', 'The North American release of the colorful Pac-Man platforming hit.', 'Pac-Land (USA) on TurboGrafx-16 offers classic 16-bit platforming fun. Help Pac-Man navigate through towns and forests in this faithful and polished arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachio-kun---juuban-shoubu-japan', 'Turbografx-16', 'Pachio Kun - Juuban Shoubu (Japan)', '1990', 'Gambling', 'Coconuts Japan', '1', 'Pachinko simulation', 'Pachinko simulation featuring the series mascot.', 'Win at various Pachinko parlors to build your fortune.', 'A charming Japan-exclusive sim with RPG-style exploration elements.', 'Pachio Kun: Juuban Shoubu (Japan) for TurboGrafx-16 provides an authentic 16-bit Pachinko experience. Master the machines and explore the vibrant 16-bit parlors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panza-kick-boxing-usa', 'Turbografx-16', 'Panza Kick Boxing (USA)', '1990', 'Sports', 'Micro World', '1-2', 'Arcade kickboxing', 'One-on-one professional kickboxing simulation.', 'Train your fighter and win the world championship through strategy.', 'A technical fighting game with detailed sprites and customizable moves.', 'Panza Kick Boxing (USA) on TurboGrafx-16 offers a realistic and deep combat sim. Master the timing and combinations to dominate the ring in this 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paranoia-japan', 'Turbografx-16', 'Paranoia (Japan)', '1990', 'Action', 'Naxat Soft', '1', 'Psychological horror adventure', 'Horizontal-scrolling shoot ''em up with organic themes.', 'Pilot a bio-ship through alien environments to stop a parasitic threat.', 'A dark and atmospheric shooter known for its Giger-esque art style.', 'Paranoia (Japan) for TurboGrafx-16, known as Psychosis in the West, offers a surreal 16-bit shooting experience. Battle through biological horrors in this unique shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parasol-stars---the-story-of-bubble-bobble-iii-japan', 'Turbografx-16', 'Parasol Stars - The Story of Bubble Bobble III (Japan)', '1991', 'Platformer', 'Taito', '1', 'Cute umbrella platformer', 'Single-screen action-platformer with parasol-based combat.', 'Use magical parasols to stun and throw enemies across colorful worlds.', 'The official sequel to Rainbow Islands and a masterpiece of the system.', 'Parasol Stars (Japan) on TurboGrafx-16 is a pinnacle of 16-bit platforming. Experience incredible music and polished gameplay in this essential Taito classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parasol-stars---the-story-of-bubble-bobble-iii-usa', 'Turbografx-16', 'Parasol Stars - The Story of Bubble Bobble III (USA)', '1991', 'Platformer', 'Taito', '1', 'Cute umbrella platformer', 'Single-screen action-platformer with parasol-based combat.', 'Use magical parasols to stun and throw enemies across colorful worlds.', 'The highly acclaimed North American release of the Bubble Bobble sequel.', 'Parasol Stars (USA) for TurboGrafx-16 delivers pure arcade joy. Master the physics of your parasol to clear diverse and vibrant 16-bit stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parodius-da!---shinwa-kara-owarai-he-japan', 'Turbografx-16', 'Parodius da! - Shinwa Kara Owarai he (Japan)', '1990', 'Shooter', 'Konami', '1', 'Comedy vertical shooter', 'Horizontal-scrolling "cute ''em up" parodying Gradius.', 'Pilot bizarre characters through humorous versions of classic shooter levels.', 'A hilarious and technically impressive port of the Konami arcade hit.', 'Parodius da! (Japan) on TurboGrafx-16 is a visual and musical masterpiece. Experience frantic 16-bit shooting with a comedic twist in this essential shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pc-denjin---punkic-cyborgs-japan', 'Turbografx-16', 'PC Denjin - Punkic Cyborgs (Japan)', '1990', 'Action', 'Hudson Soft', '1', 'Fast arcade platformer', 'Horizontal-scrolling shoot ''em up spinoff of the Bonk series.', 'Pilot the robotic Zonk to blast through futuristic 16-bit worlds.', 'A high-energy "cute ''em up" known as Air Zonk in North America.', 'PC Denjin (Japan) for TurboGrafx-16 features incredible sprite work and music. Experience the cyberpunk side of the Bonk universe in this polished shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pc-genjin---pithecanthropus-computerurus-japan', 'Turbografx-16', 'PC Genjin - Pithecanthropus Computerurus (Japan)', '1989', 'Platformer', 'Hudson Soft', '1', 'Prehistoric mascot platformer', 'Side-scrolling platformer featuring the system''s mascot.', 'Use your head-butt attacks to rescue Princess Za from King Drool.', 'The Japanese original of the legendary Bonk''s Adventure.', 'PC Genjin (Japan) on TurboGrafx-16 is the game that defined the PC Engine. Experience the iconic 16-bit platforming that made the caveman a superstar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pc-genjin-2---pithecanthropus-computerurus-japan', 'Turbografx-16', 'PC Genjin 2 - Pithecanthropus Computerurus (Japan)', '1991', 'Platformer', 'Hudson Soft', '1', 'Prehistoric mascot sequel', 'Side-scrolling platformer with enhanced graphics and moves.', 'Stop King Drool again in a quest featuring multiple transformations.', 'The Japanese version of the fan-favorite Bonk''s Revenge.', 'PC Genjin 2 (Japan) for TurboGrafx-16 is often cited as the best in the trilogy. Experience refined 16-bit mechanics and brilliant level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pc-genjin-3---pithecanthropus-computerurus-japan', 'Turbografx-16', 'PC Genjin 3 - Pithecanthropus Computerurus (Japan)', '1993', 'Platformer', 'Hudson Soft', '1', 'Late-era mascot platformer', 'Side-scrolling platformer with size-changing mechanics.', 'Use shrinking and growing candies to navigate complex new levels.', 'The third and final 16-bit entry in the legendary Bonk series.', 'PC Genjin 3 (Japan) on TurboGrafx-16 adds a unique cooperative mode and massive bosses. Experience the peak of 16-bit prehistoric platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pc-pachi-slot-japan', 'Turbografx-16', 'PC Pachi-Slot (Japan)', '1989', 'Gambling', 'Hudson Soft', '1', 'Slot machine simulator', 'Digital Pachi-Slot gambling simulation.', 'Master the slot machines in various parlors to win virtual credits.', 'A realistic sim featuring multiple machine types and betting options.', 'PC Pachi-Slot (Japan) for TurboGrafx-16 brings the Japanese parlor home. Experience high-fidelity 16-bit slot machine simulation in this polished title.');
